/* =====================================================================
   InvoicePrint - Datos sintéticos de prueba
   Generado por generar_seed.py  (seed=20261109, fecha de referencia=2026-11-09)
   Requiere haber ejecutado antes InvocePrint.sql (estructura).

   Volumen: empresa=3, impuestos=6, series_folios=6, clientes=45, productos=30, facturas=240, detalles_factura=837, pagos=187

   Convenciones de datos:
   - detalles_factura.total = (cantidad*precio_unitario - descuento) + impuesto_monto
   - facturas.subtotal = SUM(base), impuesto_total = SUM(impuesto_monto), total = subtotal + impuesto_total
   - estatus: Borrador | Pendiente | Parcial | Pagada | Vencida | Cancelada | Timbrada (nota de crédito)
   - Pagada => SUM(pagos) = total; Parcial => 0 < SUM(pagos) < total; resto sin pagos
   - Borrador => uuid NULL. PPD => forma_pago '99 - Por definir'.
   - facturas.folio: consecutivo por serie; series_folios.folio_actual = último folio asignado.

   @limpiar = 1 BORRA todos los datos de las 8 tablas y reinicia identidades.
   ===================================================================== */
USE [InvoicePrint];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET QUOTED_IDENTIFIER ON;   -- requerido por el índice filtrado UX_facturas_serie_folio
SET ANSI_NULLS ON;

DECLARE @limpiar BIT = 0;   -- <<< cambiar a 1 para vaciar las tablas antes de cargar

IF @limpiar = 0 AND (EXISTS (SELECT 1 FROM dbo.empresa) OR EXISTS (SELECT 1 FROM dbo.facturas) OR EXISTS (SELECT 1 FROM dbo.clientes)
    OR EXISTS (SELECT 1 FROM dbo.productos) OR EXISTS (SELECT 1 FROM dbo.impuestos) OR EXISTS (SELECT 1 FROM dbo.series_folios))
BEGIN
    ;THROW 50001, N'Las tablas ya contienen datos. Cambie @limpiar a 1 para reemplazarlos.', 1;
END

BEGIN TRANSACTION;

IF @limpiar = 1
BEGIN
    DELETE FROM dbo.pagos;
    DELETE FROM dbo.detalles_factura;
    DELETE FROM dbo.facturas;
    DELETE FROM dbo.productos;
    DELETE FROM dbo.clientes;
    DELETE FROM dbo.series_folios;
    DELETE FROM dbo.impuestos;
    DELETE FROM dbo.empresa;
    DBCC CHECKIDENT ('dbo.pagos', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.detalles_factura', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.facturas', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.productos', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.clientes', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.series_folios', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.impuestos', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.empresa', RESEED, 0) WITH NO_INFOMSGS;
END

/* ---------- empresa (3) ---------- */
SET IDENTITY_INSERT dbo.empresa ON;
SET IDENTITY_INSERT dbo.empresa OFF;
DBCC CHECKIDENT ('dbo.empresa', RESEED) WITH NO_INFOMSGS;

/* ---------- impuestos (6) ---------- */
SET IDENTITY_INSERT dbo.impuestos ON;
SET IDENTITY_INSERT dbo.impuestos OFF;
DBCC CHECKIDENT ('dbo.impuestos', RESEED) WITH NO_INFOMSGS;

/* ---------- series_folios (6) ---------- */
SET IDENTITY_INSERT dbo.series_folios ON;
SET IDENTITY_INSERT dbo.series_folios OFF;
DBCC CHECKIDENT ('dbo.series_folios', RESEED) WITH NO_INFOMSGS;

/* ---------- clientes (45) ---------- */
SET IDENTITY_INSERT dbo.clientes ON;
SET IDENTITY_INSERT dbo.clientes OFF;
DBCC CHECKIDENT ('dbo.clientes', RESEED) WITH NO_INFOMSGS;

/* ---------- productos (30) ---------- */
SET IDENTITY_INSERT dbo.productos ON;
SET IDENTITY_INSERT dbo.productos OFF;
DBCC CHECKIDENT ('dbo.productos', RESEED) WITH NO_INFOMSGS;

/* ---------- facturas (240) ---------- */
SET IDENTITY_INSERT dbo.facturas ON;
SET IDENTITY_INSERT dbo.facturas OFF;
DBCC CHECKIDENT ('dbo.facturas', RESEED) WITH NO_INFOMSGS;

/* ---------- detalles_factura (837) ---------- */
SET IDENTITY_INSERT dbo.detalles_factura ON;
SET IDENTITY_INSERT dbo.detalles_factura OFF;
DBCC CHECKIDENT ('dbo.detalles_factura', RESEED) WITH NO_INFOMSGS;

/* ---------- pagos (187) ---------- */
SET IDENTITY_INSERT dbo.pagos ON;
SET IDENTITY_INSERT dbo.pagos OFF;
DBCC CHECKIDENT ('dbo.pagos', RESEED) WITH NO_INFOMSGS;

COMMIT TRANSACTION;
PRINT N'Datos sintéticos cargados correctamente.';
GO

/* ---------- Verificaciones (deben devolver 0 filas en las consultas de inconsistencias) ---------- */
SELECT 'empresa' tabla, COUNT(*) filas FROM dbo.empresa UNION ALL SELECT 'impuestos', COUNT(*) FROM dbo.impuestos
UNION ALL SELECT 'series_folios', COUNT(*) FROM dbo.series_folios UNION ALL SELECT 'clientes', COUNT(*) FROM dbo.clientes
UNION ALL SELECT 'productos', COUNT(*) FROM dbo.productos UNION ALL SELECT 'facturas', COUNT(*) FROM dbo.facturas
UNION ALL SELECT 'detalles_factura', COUNT(*) FROM dbo.detalles_factura UNION ALL SELECT 'pagos', COUNT(*) FROM dbo.pagos;

-- Facturas cuyo encabezado no cuadra con sus detalles
SELECT f.factura_id, f.total, SUM(d.total) suma_detalles
FROM dbo.facturas f JOIN dbo.detalles_factura d ON d.factura_id = f.factura_id
GROUP BY f.factura_id, f.total, f.impuesto_total
HAVING f.total <> SUM(d.total) OR f.impuesto_total <> SUM(d.impuesto_monto);

-- Estatus de pago incoherente con los pagos registrados
SELECT f.factura_id, f.estatus, f.total, ISNULL(p.pagado,0) pagado
FROM dbo.facturas f LEFT JOIN (SELECT factura_id, SUM(monto) pagado FROM dbo.pagos GROUP BY factura_id) p ON p.factura_id = f.factura_id
WHERE (f.estatus = N'Pagada' AND ISNULL(p.pagado,0) <> f.total)
   OR (f.estatus = N'Parcial' AND NOT (ISNULL(p.pagado,0) > 0 AND p.pagado < f.total))
   OR (f.estatus NOT IN (N'Pagada', N'Parcial') AND ISNULL(p.pagado,0) <> 0);

-- Resumen por estatus
SELECT estatus, moneda, COUNT(*) facturas, SUM(total) total FROM dbo.facturas GROUP BY estatus, moneda ORDER BY estatus, moneda;
GO
